sys_script_include.script:
var pdf_kotak_uw_portal = Class.create();
pdf_kotak_uw_portal.prototype = {
        initialize: function() {},

        job_id_pdf: function(jobIDSys) {

            var content = '';

            //CSS styles
            content += '<style>';
            content += 'table { width: 100%; border-collapse: collapse; margin-bottom: 20px; }';
            content += 'th, td { border: 1px solid black; padding: 8px; text-align: left; }';
            content += 'th { background-color: #f2f2f2; font-weight: bold; }';
            content += '.section-header { font-size: 16px; color: #3498db; border-bottom: 2px solid #3498db; padding-bottom: 5px; margin: 20px 0; }';
            content += '.status-table { margin-bottom: 30px; }';
            content += '.failed-reason-table { margin-top: 20px; }';
            content += '.centered { text-align: center; }';
            content += '.failed-cell { color: #e74c3c; }';
            content += '.main-heading { text-align: center; font-size: 24px; font-weight: bold; color: #2c3e50; margin: 20px 0 30px 0; border-bottom: 3px double #2c3e50; padding-bottom: 10px; }';
            content += '</style>';

            var jobGR = new GlideRecord('x_rptp_kotak_upload_excel');
            jobGR.addQuery('sys_id', jobIDSys);
            jobGR.query();

            if (jobGR.next()) {

                content += '<div class="main-heading">Report on Excel Upload</div>';
                content += '<div class="section-header">Excel upload Summary</div>';
                content += '<table class="status-table">';
                content += '<tr>';
                content += '<th>Job ID</th>';
                content += '<th>Date & Time of upload</th>';
                content += '<th>Count of Total Uploads</th>';
                content += '<th>Successful Uploads</th>';
                content += '<th>Failed Uploads</th>';
                content += '</tr>';

                content += '<tr>';
                content += '<td class="centered">' + jobGR.getValue('number') + '</td>';
                content += '<td class="centered">' + jobGR.getValue('date_time_of_upload') + '</td>';
                content += '<td class="centered">' + jobGR.getValue('count_of_total_uploads') + '</td>';
                content += '<td class="centered">' + jobGR.getValue('successful') + '</td>';
                content += '<td class="centered failed-cell">' + jobGR.getValue('failed') + '</td>';
                content += '</tr>';
                content += '</table>';

                if (jobGR.getValue('failed') != "0") {

                    content += '<div class="section-header">Failed Records Reason</div>';
                    content += '<table class="failed-reason-table">';
                    content += '<tr>';
                    content += '<th style="width: 100%; min-height: 100px;">Reason</th>';
                    content += '</tr>';

                    content += '<tr>';
                    content += '<td style="min-height: 150px; white-space: pre-wrap; padding: 15px;">' + jobGR.getValue('reason') + '</td>';
                    content += '</tr>';

                    content += '</table>';
                }

                var v = new sn_pdfgeneratorutils.PDFGenerationAPI;
                var resultt = v.convertToPDF(content, "x_rptp_kotak_upload_excel", jobIDSys, "Job Id Pdf - " + jobGR.getValue("number"));
            }
        },

        audit_trail_pdf: function(caseId, viewName, auditSys) {

            var caseGR = new GlideRecord('x_rptp_kotak_uw_case');
            caseGR.addQuery("sys_id", caseId);
            caseGR.query();

            if (caseGR.next()) {

                var loanNumber = caseGR.getDisplayValue("loan_number");
                var memberNumber = caseGR.getDisplayValue("consumer_id");
                var dataHtml = "";

                //header style
                dataHtml += '<style>';
                dataHtml += 'table { width: 100%; border-collapse: collapse; margin-bottom: 20px; }';
                dataHtml += 'th, td { border: 1px solid black; padding: 8px; text-align: left; }';
                dataHtml += 'th { background-color: #f2f2f2; }';
                dataHtml += '.section-header { font-size: 14px; font-weight: bold; margin-top: 20px; margin-bottom: 10px; }';
                dataHtml += '.main-heading { text-align: center; font-size: 24px; font-weight: bold; color: #2c3e50; margin: 20px 0 30px 0; border-bottom: 3px double #2c3e50; padding-bottom: 10px; }';
                dataHtml += '</style>';

                dataHtml += '<div class="main-heading">AUDIT TRAIL of LOAN NO: ' + loanNumber + " - " + memberNumber + '</div>';

                // Coverage Details Section
                dataHtml += "<div><h4 style=\"color: #3498db; border-bottom: 2px solid #3498db; padding-bottom: 5px; margin-bottom: 20px;\">" + "Coverage Details" + "</h4></div>";
                dataHtml += '<table>';
                dataHtml += '<tr><th>Details</th><th>Value</th></tr>';

                var fields = this._getNonEmptyFieldsForView(caseGR, viewName);
                dataHtml = dataHtml + this._generateHtml(fields);

                dataHtml += '</table>';


                // Audit Trail Section
                dataHtml += "<div><h4 style=\"color: #3498db; border-bottom: 2px solid #3498db; padding-bottom: 5px; margin-bottom: 20px;\">" + "Activity" + "</h4></div>";
                dataHtml += '<table>';
                dataHtml += '<tr><th>Action</th><th>Timestamp</th></tr>';

                // Get audit trail records
                var auditGR = new GlideRecord('x_rptp_kotak_kotak_audit_trail');
                auditGR.addQuery('case_id', caseId);
                //auditGR.addEncodedQuery("activity!=Audit Trail of the Case was sent via Email^ORactivity=NULL")
                auditGR.orderBy('sys_created_on');
                auditGR.query();

                while (auditGR.next()) {
                    dataHtml += '<tr>';
                    dataHtml += '<td>' + auditGR.getValue("activity") + '</td>';
                    dataHtml += '<td>' + auditGR.getValue("sys_created_on") + '</td>';
                    dataHtml += '</tr>';
                }

                dataHtml += '</table>';

                // Generate PDF
                var v = new sn_pdfgeneratorutils.PDFGenerationAPI;
                var resultt = v.convertToPDF(dataHtml, "x_rptp_kotak_kotak_audit_trail", auditSys, "AUDIT TRAIL of LOAN NO: " + loanNumber + " - " + memberNumber);
            }
        },

        case_sheet_pdf: function(caseId, viewName, auditSys) {

            var caseGR = new GlideRecord('x_rptp_kotak_uw_case');
            caseGR.addQuery("sys_id", caseId);
            caseGR.query();

            if (caseGR.next()) {

                var loanNumber = caseGR.getDisplayValue("loan_number");
                var memberNumber = caseGR.getDisplayValue("consumer_id");
                var dataHtml = "";

                //header style
                dataHtml += '<style>';
                dataHtml += 'table { width: 100%; border-collapse: collapse; margin-bottom: 20px; }';
                dataHtml += 'th, td { border: 1px solid black; padding: 8px; text-align: left; }';
                dataHtml += 'th { background-color: #f2f2f2; }';
                dataHtml += '.section-header { font-size: 14px; font-weight: bold; margin-top: 20px; margin-bottom: 10px; }';
                dataHtml += '.main-heading { text-align: center; font-size: 24px; font-weight: bold; color: #2c3e50; margin: 20px 0 30px 0; border-bottom: 3px double #2c3e50; padding-bottom: 10px; }';
                dataHtml += '</style>';

                dataHtml += '<div class="main-heading">Case Sheet</div>';

                // Coverage Details Section
                dataHtml += "<div><h4 style=\"color: #3498db; border-bottom: 2px solid #3498db; padding-bottom: 5px; margin-bottom: 20px;\">" + "Coverage Details" + "</h4></div>";
                dataHtml += '<table>';
                dataHtml += '<tr><th>Details</th><th>Value</th></tr>';

                var fields = this._getNonEmptyFieldsForView(caseGR, viewName);
                dataHtml = dataHtml + this._generateHtml(fields);

                dataHtml += '</table>';


                // Get UW Decision records
                var DecisionGr = new GlideRecord('x_rptp_kotak_underwriter_decision');
                DecisionGr.addQuery('case_id', caseId);
                //auditGR.addEncodedQuery("activity!=Audit Trail of the Case was sent via Email^ORactivity=NULL")
                DecisionGr.orderBy('sys_created_on');
                DecisionGr.query();

                dataHtml += "<div><h4 style=\"color: #3498db; border-bottom: 2px solid #3498db; padding-bottom: 5px; margin-bottom: 20px;\">" + "Decisions" + "</h4></div>";


                if (!DecisionGr.hasNext()) {
                    // Add a message indicating no decisions are found
                    dataHtml += "<div style=\"font-family: Arial, sans-serif; color: #d9534f; margin: 20px auto; text-align: center; font-weight: bold;\">No decisions available for this case.</div>";
                } else {
                    while (DecisionGr.next()) {
                        // Start the container for each decision record
                        dataHtml += "<div style=\"max-width: 900px; margin: 20px auto; font-family: Arial, sans-serif; border: 1px solid #ddd; border-radius: 10px; box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1); overflow: hidden;\">";

                        // Header section
                        dataHtml += "<div style=\"background-color: #f8f9fa; padding: 15px;\">";
                        dataHtml += "<h3 style=\"font-size: 15px; color: #003366; margin: 0; font-weight: bold;\">User ID: " + DecisionGr.getValue("sys_created_by") + ";   Date & Time: " + DecisionGr.getValue("sys_updated_on") + "</h3>";
                        dataHtml += "</div>";

                        // Table for content
                        dataHtml += "<table style=\"width: 100%; border-collapse: collapse; margin: 20px 0; font-family: Arial, sans-serif;\">";
                        dataHtml += "<tbody>";

                        //UW Decision
                        dataHtml += "<tr>";
                        dataHtml += "<td style=\"border: 1px solid #ddd; padding: 8px; font-weight: bold; color: #333;\">" + DecisionGr.getDisplayValue("u_underwriter") + " Decision</td>";
                        dataHtml += "<td style=\"border: 1px solid #ddd; padding: 8px; color: #555;\">" + DecisionGr.getDisplayValue("decision") + "</td>";
                        dataHtml += "</tr>";

                        //UW Comments
                        dataHtml += "<tr>";
                        dataHtml += "<td style=\"border: 1px solid #ddd; padding: 8px; font-weight: bold; color: #333;\">" + DecisionGr.getDisplayValue("u_underwriter") + " Comments</td>";
                        dataHtml += "<td style=\"border: 1px solid #ddd; padding: 8px; color: #555;\">" + DecisionGr.getValue("comments") + "</td>";
                        dataHtml += "</tr>";

                        //UW Remarks
                        dataHtml += "<tr>";
                        dataHtml += "<td style=\"border: 1px solid #ddd; padding: 8px; font-weight: bold; color: #333;\">" + DecisionGr.getDisplayValue("u_underwriter") + " Remarks</td>";
                        dataHtml += "<td style=\"border: 1px solid #ddd; padding: 8px; color: #555;\">" + DecisionGr.getValue("remarks") + "</td>";
                        dataHtml += "</tr>";

                        dataHtml += "</tbody>";
                        dataHtml += "</table>";
                        dataHtml += "</div>";

                    }

                    // Generate PDF
                    var v = new sn_pdfgeneratorutils.PDFGenerationAPI;
                    var resultt = v.convertToPDF(dataHtml, "x_rptp_kotak_kotak_audit_trail", auditSys, "CASE SHEET of LOAN NO: " + loanNumber + " - " + memberNumber);
                }
			}
            },

            _getNonEmptyFieldsForView: function(viewTable, viewName) {
                    var fields = [];
                    var viewSysID = "";

                    var SysView = new GlideRecord("sys_ui_view");
                    SysView.addQuery("name", viewName);
                    SysView.query();

                    if (SysView.next()) {
                        viewSysID = SysView.getValue("sys_id");
                    }

                    var ga = new GlideRecord('sys_ui_section');
                    ga.addQuery('name', viewTable.getTableName());
                    ga.addQuery('view', viewSysID);
                    ga.query();

                    while (ga.next()) {
                        var elementGa = new GlideRecord('sys_ui_element');
                        elementGa.addQuery('sys_ui_section', ga.getUniqueValue());
                        elementGa.orderBy('position');
                        elementGa.query();

                        while (elementGa.next()) {
                            var fieldName = elementGa.getValue('element');

                            if (fieldName) {
                                var element = viewTable.getElement(fieldName);
                                if (element) {
                                    var fieldValue = this._getFieldValue(viewTable, fieldName);
                                    var fieldLabel = element.getLabel();
                                    if (fieldValue !== null && fieldValue !== '') {
                                        fields.push({
                                            name: fieldName,
                                            label: fieldLabel,
                                            value: fieldValue
                                        });
                                    }
                                }
                            }
                        }
                    }
                    return fields;
                },

                _getFieldValue: function(gr, fieldName) {
                    var element = gr.getElement(fieldName);
                    var value;

                    if (element.getED().getInternalType() == 'boolean') {
                        if (gr.getDisplayValue(fieldName) == "true") {
                            value = "Yes";
                        } else {
                            value = "No";
                        }
                    } else {
                        value = gr.getDisplayValue(fieldName);
                    }

                    return (value !== null && value !== undefined) ? '' + value : value;
                },

                _generateHtml: function(fields) {
                    var html = "";
                    // var html = '<div style="width: 100%; max-width: 800px; margin: 0 auto;">'; // Container to center content
                    // html += '<table style="width: 100%; border-collapse: collapse; text-align: center;">'; // Added text-align: center to table
                    for (var i = 0; i < fields.length; i++) {
                        var field = fields[i];
                        html += '<tr>'; // Start of row
                        html += '<td style="width: 50%; padding: 5px 10px; text-align: left; font-weight: bold; vertical-align: top;">' + field.label + ' :</td>';
                        html += '<td style="width: 50%; padding: 5px 10px; text-align: left; vertical-align: top;">' + field.value + '</td>';
                        html += '</tr>';
                    }
                    html += '</table>';
                    html += '</div>';
                    return html;
                },

                type: 'pdf_kotak_uw_portal'
        };
